export function summarizeSkillChange(input = {}) {
  const title = String(input.title ?? '').trim();
  const evidence = Array.isArray(input.evidence) ? input.evidence.filter(Boolean) : [];
  const risk = String(input.risk ?? 'low').toLowerCase();
  return { title, evidenceCount: evidence.length, readyForReview: evidence.length > 0 && risk !== 'high' };
}
